// Reine Rechen- und Textfunktionen: kein `$`, damit Entscheidungen und
// Beschriftungen an einer Stelle stehen und leicht zu prüfen sind.
import type { PluginOptions, SessionUsage } from 'claude-code'

import type { Auto, OffReason, Usage } from '../types'

export const MINUTE = 60_000
export const HOUR = 60 * MINUTE

/** Die Einstellungen in Millisekunden bzw. Prozent. */
export type Settings = {
  cacheMs: number
  pingLeadMs: number
  maxOnMs: number
  limitPercent: number
  warnLeadMs: number
}

export type SettingDefaults = {
  cacheMinutes: number
  pingLeadMinutes: number
  maxHours: number
  limitPercent: number
  warnLeadMinutes: number
}

function positive(value: unknown, fallback: number): number {
  const n = typeof value === 'number' ? value : Number(value)
  return Number.isFinite(n) && n > 0 ? n : fallback
}

export function readSettings(options: PluginOptions, defaults: SettingDefaults): Settings {
  const cacheMinutes = positive(options['cacheMinutes'], defaults.cacheMinutes)
  // Ein Vorlauf, der so lang ist wie das ganze Fenster, ergäbe Dauerpings bzw. Dauerwarnung.
  const lead = (key: string, fallback: number) =>
    Math.min(positive(options[key], fallback), Math.max(cacheMinutes - 0.5, 0.5))

  return {
    cacheMs: cacheMinutes * MINUTE,
    pingLeadMs: lead('pingLeadMinutes', defaults.pingLeadMinutes) * MINUTE,
    maxOnMs: positive(options['maxHours'], defaults.maxHours) * HOUR,
    limitPercent: Math.min(positive(options['limitPercent'], defaults.limitPercent), 100),
    warnLeadMs: lead('warnLeadMinutes', defaults.warnLeadMinutes) * MINUTE,
  }
}

/** Was die Engine liefert, auf die Werte der Zeile verdichtet. */
export function toUsage(usage: SessionUsage): Usage {
  const fiveHour = usage.rateLimits.find(limit => limit.kind === 'five_hour')
  const weekly = usage.rateLimits.find(limit => limit.kind === 'seven_day')
  const resetsAt = fiveHour?.resetsAt === undefined ? NaN : Date.parse(fiveHour.resetsAt)

  return {
    contextTokens: usage.context.tokens ?? null,
    contextWindow: usage.context.window > 0 ? usage.context.window : null,
    contextPercent: usage.context.percent ?? null,
    fiveHourPercent: fiveHour?.percentUsed ?? null,
    fiveHourResetsAt: Number.isFinite(resetsAt) ? resetsAt : null,
    weeklyPercent: weekly?.percentUsed ?? null,
    costUsd: usage.cost?.usd ?? null,
  }
}

// ---------------------------------------------------------------------------
// Entscheidungen

/** Alles, was über Warnung, Ping und Selbstabschaltung entscheidet. */
export type Snapshot = {
  now: number
  isWorking: boolean
  lastAnswerAt: number | null
  pingedFor: number | null
  warnedFor: number | null
  auto: Auto
  usage: Usage | null
}

export type Step =
  | { kind: 'none' }
  | { kind: 'switch-off'; reason: OffReason }
  | { kind: 'ping' }
  | { kind: 'warn' }

export function remainingMs(s: Pick<Snapshot, 'now' | 'lastAnswerAt'>, cfg: Settings): number | null {
  return s.lastAnswerAt === null ? null : s.lastAnswerAt + cfg.cacheMs - s.now
}

/** Der nächste fällige Schritt; nach einer Selbstabschaltung erneut fragen. */
export function nextStep(s: Snapshot, cfg: Settings): Step {
  const remaining = remainingMs(s, cfg)
  if (remaining === null) {
    return { kind: 'none' }
  }

  if (s.auto.isOn) {
    if (s.auto.since !== null && s.now - s.auto.since >= cfg.maxOnMs) {
      return { kind: 'switch-off', reason: 'max-duration' }
    }
    if ((s.usage?.fiveHourPercent ?? 0) >= cfg.limitPercent) {
      return { kind: 'switch-off', reason: 'limit' }
    }
    if (s.isWorking) {
      return { kind: 'none' }
    }
    if (remaining <= 0) {
      return { kind: 'switch-off', reason: 'expired' }
    }
    if (remaining <= cfg.pingLeadMs && s.pingedFor !== s.lastAnswerAt) {
      return { kind: 'ping' }
    }
    return { kind: 'none' }
  }

  if (!s.isWorking && remaining > 0 && remaining <= cfg.warnLeadMs && s.warnedFor !== s.lastAnswerAt) {
    return { kind: 'warn' }
  }
  return { kind: 'none' }
}

/** Die rote Zeile steht, solange für dieses Fenster gewarnt wurde und es noch läuft. */
export function isWarningVisible(s: Snapshot, cfg: Settings): boolean {
  const remaining = remainingMs(s, cfg)
  return (
    !s.auto.isOn &&
    !s.isWorking &&
    remaining !== null &&
    remaining > 0 &&
    s.warnedFor === s.lastAnswerAt
  )
}

export function isCompactOffered(s: Snapshot, cfg: Settings): boolean {
  if (s.isWorking || s.lastAnswerAt === null) {
    return false
  }
  const remaining = remainingMs(s, cfg) ?? 0
  return (
    isWarningVisible(s, cfg) ||
    (s.usage?.contextPercent ?? 0) >= 50 ||
    (remaining > 0 && remaining < 10 * MINUTE)
  )
}

// ---------------------------------------------------------------------------
// Darstellung
//
// Die Zeile wird als Daten beschrieben (Teile mit Text und Ton), damit sich ihre
// Breite vorab berechnen lässt. In Stufen wird sie knapper, bis sie in eine Zeile
// passt; erst wenn auch die knappste nicht passt, kommen zwei Zeilen.

export type Level = 'success' | 'warning' | 'error'

/** Wie ein Teil gezeichnet wird: in einer Ampelfarbe, in Claudes Farbe, abgeblendet oder normal. */
export type Tone = Level | 'claude' | 'dim' | 'plain'

export type Part = { text: string; tone: Tone }

/** Ein Abschnitt der Zeile (Cache, Kontext, 5h, Woche, Kosten). */
export type Segment = { key: string; parts: Part[] }

/** Ein Knopf mit kurzem Text daneben. */
export type Control = {
  key: 'auto' | 'compact'
  label: string
  hint: string | null
  isPrimary: boolean
}

/** 0 ausführlich, 1 knapp (ohne Tokenzahlen, kurze Knöpfe), 2 minimal (ohne Balken). */
export type Density = 0 | 1 | 2

export type StatusLine = { segments: Segment[]; controls: Control[] }

export type StatusLayout = {
  density: Density
  /** Eine Zeile, oder zwei: Cache und Knöpfe oben, Werte unten. */
  lines: StatusLine[]
}

export type WarningLayout = { text: string; pingLabel: string; compactLabel: string }

const SEPARATOR = ' │ '
const GAP = '  '
/** Spielraum, weil nicht jede Oberfläche Zeichen exakt gleich breit setzt. */
const SLACK = 2

export function remainingLevel(ms: number): Level {
  if (ms <= 5 * MINUTE) return 'error'
  if (ms <= 15 * MINUTE) return 'warning'
  return 'success'
}

export function percentLevel(percent: number): Level {
  if (percent >= 80) return 'error'
  if (percent >= 50) return 'warning'
  return 'success'
}

/** Minuten, aufgerundet; ab 60 als Stunden:Minuten („1:05 h“). */
export function formatDuration(ms: number): string {
  const minutes = Math.max(0, Math.ceil(ms / MINUTE))
  if (minutes < 60) {
    return `${minutes} min`
  }
  return `${Math.floor(minutes / 60)}:${String(minutes % 60).padStart(2, '0')} h`
}

export function formatPercent(percent: number): string {
  return `${Math.round(percent)}%`
}

export function formatTokens(tokens: number): string {
  if (tokens < 1000) {
    return String(Math.round(tokens))
  }
  if (tokens < 1_000_000) {
    return `${Math.round(tokens / 1000)}k`
  }
  return `${(Math.round(tokens / 100_000) / 10).toString().replace('.', ',')}M`
}

export function formatUsd(usd: number): string {
  return `${usd.toFixed(2).replace('.', ',')} $`
}

export function formatHours(ms: number): string {
  const hours = Math.round((ms / HOUR) * 10) / 10
  return `${hours.toString().replace('.', ',')} h`
}

/** Ein Balken aus gleich großen Zeichen: der volle Teil farbig, der leere abgeblendet. */
export function bar(percent: number, level: Level, width: number): Part[] {
  const filled = Math.round((Math.min(Math.max(percent, 0), 100) / 100) * width)
  return [
    { text: '▰'.repeat(filled), tone: level },
    { text: '▰'.repeat(width - filled), tone: 'dim' },
  ].filter(part => part.text !== '') as Part[]
}

export type CacheView =
  | { kind: 'none' }
  | { kind: 'working' }
  | { kind: 'warm'; remaining: number }
  | { kind: 'expired' }

export function cacheView(s: Snapshot, cfg: Settings): CacheView {
  const remaining = remainingMs(s, cfg)
  if (s.isWorking) return { kind: 'working' }
  if (remaining === null) return { kind: 'none' }
  if (remaining <= 0) return { kind: 'expired' }
  return { kind: 'warm', remaining }
}

function cacheSegment(view: CacheView, d: Density): Segment {
  const label = d < 2 ? 'Cache ' : ''
  const part: Part =
    view.kind === 'none'
      ? { text: `◌ ${label}noch keine Antwort`, tone: 'dim' }
      : view.kind === 'working'
        ? { text: `◐ ${label}Claude arbeitet`, tone: 'claude' }
        : view.kind === 'expired'
          ? { text: `○ ${label}abgelaufen`, tone: 'error' }
          : { text: `● ${label}${formatDuration(view.remaining)}`, tone: remainingLevel(view.remaining) }
  return { key: 'cache', parts: [part] }
}

function metricSegments(usage: Usage | null, now: number, d: Density): Segment[] {
  const segments: Segment[] = []
  const barWidth = d === 0 ? 6 : 4
  const metric = (label: string, percent: number): Part[] => [
    { text: label, tone: 'dim' },
    ...(d < 2 ? [...bar(percent, percentLevel(percent), barWidth), { text: ' ', tone: 'plain' as const }] : []),
    { text: formatPercent(percent), tone: percentLevel(percent) },
  ]

  if (usage?.contextPercent != null) {
    const parts = metric(d < 2 ? 'Kontext ' : 'Ktx ', usage.contextPercent)
    if (d === 0 && usage.contextTokens != null && usage.contextWindow != null) {
      parts.push({
        text: ` ${formatTokens(usage.contextTokens)}/${formatTokens(usage.contextWindow)}`,
        tone: 'dim',
      })
    }
    segments.push({ key: 'kontext', parts })
  }
  if (usage?.fiveHourPercent != null) {
    const parts = metric('5h ', usage.fiveHourPercent)
    if (usage.fiveHourResetsAt != null) {
      const left = usage.fiveHourResetsAt - now
      parts.push({ text: ` ↻${left > 0 ? formatDuration(left) : 'gleich'}`, tone: 'dim' })
    }
    segments.push({ key: 'fuenf-stunden', parts })
  }
  if (usage?.weeklyPercent != null) {
    segments.push({
      key: 'woche',
      parts: [
        { text: d < 2 ? 'Woche ' : 'Wo ', tone: 'dim' },
        { text: formatPercent(usage.weeklyPercent), tone: percentLevel(usage.weeklyPercent) },
      ],
    })
  }
  if (usage?.costUsd != null) {
    segments.push({ key: 'kosten', parts: [{ text: formatUsd(usage.costUsd), tone: 'dim' }] })
  }
  return segments
}

/** Kurztext neben dem Schalter: wann gepingt wird, oder warum er aus ist. */
export function autoHint(s: Snapshot, cfg: Settings, isPingWaiting: boolean, d: Density = 0): string | null {
  const isLong = d === 0
  if (!s.auto.isOn) {
    switch (s.auto.offReason) {
      case 'max-duration':
        return isLong ? `nach ${formatHours(cfg.maxOnMs)} abgeschaltet` : `aus nach ${formatHours(cfg.maxOnMs)}`
      case 'limit': {
        const percent = formatPercent(s.usage?.fiveHourPercent ?? cfg.limitPercent)
        return isLong ? `abgeschaltet: 5h-Limit ${percent}` : `aus: 5h-Limit ${percent}`
      }
      case 'expired':
        return isLong ? 'abgeschaltet: Cache war abgelaufen' : 'aus: Cache war kalt'
      default:
        return null
    }
  }
  if (s.isWorking) return null
  if (s.lastAnswerAt !== null && s.pingedFor === s.lastAnswerAt) return 'Ping läuft'
  if (isPingWaiting) return isLong ? 'Ping wartet aufs leere Eingabefeld' : 'Ping wartet (Eingabe)'
  const remaining = remainingMs(s, cfg)
  if (remaining === null) return null
  const untilPing = remaining - cfg.pingLeadMs
  if (untilPing <= 0) return 'Ping gleich'
  return isLong ? `Ping in ${formatDuration(untilPing)}` : `Ping ${formatDuration(untilPing)}`
}

function controlsFor(s: Snapshot, cfg: Settings, isPingWaiting: boolean, isWarning: boolean, d: Density): Control[] {
  const controls: Control[] = []
  if (s.lastAnswerAt !== null) {
    const state = s.auto.isOn ? 'an' : 'aus'
    controls.push({
      key: 'auto',
      label: d === 0 ? `Warmhalten: ${state}` : `Warm: ${state}`,
      hint: autoHint(s, cfg, isPingWaiting, d),
      isPrimary: s.auto.isOn,
    })
  }
  // Während der Warnung steht der Knopf in der roten Zeile.
  if (!isWarning && isCompactOffered(s, cfg)) {
    controls.push({ key: 'compact', label: d === 0 ? 'Komprimieren' : '/compact', hint: null, isPrimary: false })
  }
  return controls
}

export function textWidth(text: string): number {
  return [...text].length
}

function segmentsWidth(segments: Segment[], isAfterCache: boolean): number {
  return segments.reduce(
    (sum, segment, index) =>
      sum +
      (index > 0 || isAfterCache ? SEPARATOR.length : 0) +
      segment.parts.reduce((n, part) => n + textWidth(part.text), 0),
    0,
  )
}

/** Ein Knopf ist `[ label ]` breit, sein Kurztext steht mit einem Leerzeichen daneben. */
function controlsWidth(controls: Control[]): number {
  return controls.reduce(
    (sum, control) =>
      sum + GAP.length + textWidth(control.label) + 4 + (control.hint === null ? 0 : 1 + textWidth(control.hint)),
    0,
  )
}

export function lineWidth(line: StatusLine): number {
  const [first, ...rest] = line.segments
  const firstWidth = first === undefined ? 0 : segmentsWidth([first], false)
  return firstWidth + segmentsWidth(rest, first !== undefined) + controlsWidth(line.controls)
}

/** Die ausführlichste Form, die in `columns` passt: erst einzeilig, dann zweizeilig. */
export function statusLayout(
  s: Snapshot,
  cfg: Settings,
  isPingWaiting: boolean,
  isWarning: boolean,
  columns: number,
): StatusLayout {
  const room = columns - SLACK
  const DENSITIES: Density[] = [0, 1, 2]
  const build = (d: Density) => ({
    cache: cacheSegment(cacheView(s, cfg), d),
    metrics: metricSegments(s.usage, s.now, d),
    controls: controlsFor(s, cfg, isPingWaiting, isWarning, d),
  })

  for (const d of DENSITIES) {
    const { cache, metrics, controls } = build(d)
    const line: StatusLine = { segments: [cache, ...metrics], controls }
    if (lineWidth(line) <= room) {
      return { density: d, lines: [line] }
    }
  }
  for (const d of DENSITIES) {
    const { cache, metrics, controls } = build(d)
    const top: StatusLine = { segments: [cache], controls }
    const bottom: StatusLine = { segments: metrics, controls: [] }
    if (d === 2 || Math.max(lineWidth(top), lineWidth(bottom)) <= room) {
      return { density: d, lines: metrics.length > 0 ? [top, bottom] : [top] }
    }
  }
  return { density: 2, lines: [] }
}

/** Die rote Zeile so ausführlich, wie sie in eine Zeile passt. */
export function warningLayout(remaining: number, columns: number): WarningLayout {
  const when = formatDuration(remaining)
  const forms: WarningLayout[] = [
    {
      text: `⚠ Cache wird in ${when} kalt – dann zahlt der nächste Prompt den vollen Kontextpreis`,
      pingLabel: 'Einmal warm halten',
      compactLabel: 'Kontext komprimieren',
    },
    { text: `⚠ Cache wird in ${when} kalt`, pingLabel: 'Einmal warm halten', compactLabel: 'Komprimieren' },
    { text: `⚠ kalt in ${when}`, pingLabel: 'Warm halten', compactLabel: '/compact' },
  ]
  const width = (form: WarningLayout) =>
    textWidth(form.text) + 2 * GAP.length + textWidth(form.pingLabel) + 4 + textWidth(form.compactLabel) + 4
  return forms.find(form => width(form) <= columns - SLACK) ?? forms[forms.length - 1]!
}

export function offToast(reason: OffReason, s: Snapshot, cfg: Settings): string {
  switch (reason) {
    case 'max-duration':
      return `Warmhalten ausgeschaltet: Höchstdauer von ${formatHours(cfg.maxOnMs)} erreicht.`
    case 'limit':
      return `Warmhalten ausgeschaltet: 5-Stunden-Limit bei ${formatPercent(s.usage?.fiveHourPercent ?? 0)} (Grenze ${formatPercent(cfg.limitPercent)}).`
    case 'expired':
      return 'Warmhalten ausgeschaltet: Der Cache war schon kalt, ein Ping hätte den vollen Preis gekostet.'
  }
}

export function warningToast(remaining: number): string {
  return `Prompt-Cache wird in ${formatDuration(remaining)} kalt. „Einmal warm halten“ verlängert ihn.`
}

