// Vertrag von keepcachewarm: jeder Wert, den der Mod in `$.state` hält.

/**
 * Was die Engine nach der letzten Antwort über die Session meldet; ein Wert,
 * den sie nicht liefert, ist `null` (z. B. keine Limits bei API-Nutzung).
 */
export type Usage = {
  /** Belegte Tokens im Kontextfenster. */
  contextTokens: number | null
  /** Größe des Kontextfensters in Tokens. */
  contextWindow: number | null
  /** Belegung des Kontextfensters, 0 bis 100. */
  contextPercent: number | null
  /** Verbrauch im 5-Stunden-Fenster, 0 bis 100. */
  fiveHourPercent: number | null
  /** Wann das 5-Stunden-Fenster zurückgesetzt wird, ms seit der Epoche. */
  fiveHourResetsAt: number | null
  /** Verbrauch im Wochenfenster, 0 bis 100. */
  weeklyPercent: number | null
  /** Kosten der Session in US-Dollar. */
  costUsd: number | null
}

/** Warum sich das Warmhalten selbst ausgeschaltet hat. */
export type OffReason = 'max-duration' | 'limit' | 'expired'

/** Der Schalter „automatisch warm halten“. */
export type Auto = {
  isOn: boolean
  /** Zeitpunkt des Einschaltens (ms), für die Höchstdauer. */
  since: number | null
  /** Grund der letzten Selbstabschaltung, bis der Schalter wieder betätigt wird. */
  offReason: OffReason | null
}

/** Was je Session in `$.store` liegt, damit Fortsetzen und Neuladen es behalten. */
export type SavedSession = {
  lastAnswerAt: number | null
  pingedFor: number | null
  warnedFor: number | null
  auto: Auto
  savedAt: number
}

declare module 'claude-code' {
  interface PluginState {
    keepcachewarm: {
      /** Uhr-Takt (ms); jeder Schlag zeichnet die Zeile neu. */
      now: number
      /** Die Session, zu der die Werte unten gehören. */
      sessionId: string | null
      /** Claude arbeitet gerade (Hauptschleife). */
      isWorking: boolean
      /** Zeitpunkt der letzten Antwort der Hauptschleife (ms); öffnet ein Cache-Fenster. */
      lastAnswerAt: number | null
      /** Das Fenster (`lastAnswerAt`), für das schon ein Ping verschickt wurde. */
      pingedFor: number | null
      /** Das Fenster (`lastAnswerAt`), für das schon gewarnt wurde. */
      warnedFor: number | null
      /** Ein fälliger Ping wartet, weil im Eingabefeld Text steht. */
      isPingWaiting: boolean
      auto: Auto
      usage: Usage | null
    }
  }
}
